static void FlecsGeneratedBody_World_make_alive_44a61464() {
    flecs::world ecs;

    auto e_1 = ecs.entity();
    e_1.destruct();
    test_assert(!e_1.is_alive());

    auto e_2 = ecs.entity();
    test_assert(e_1 != e_2);
    test_assert(e_1 == flecs::strip_generation(e_2));
    e_2.destruct();
    test_assert(!e_2.is_alive());

    auto e_3 = ecs.make_alive(e_2);
    test_assert(e_2 == e_3);
    test_assert(e_3.is_alive());
}

