static void FlecsGeneratedBody_World_run_post_frame_4fd43385() {
    flecs::world ecs;

    int ctx = 10;

    ecs.system()
        .run([&](flecs::iter& it) {
            while (it.next()) {
                it.world().run_post_frame([](flecs::world_t *w, void *ctx) {
                    int *i = static_cast<int*>(ctx);
                    test_int(*i, 10);
                    i[0] ++;
                }, &ctx);
            }
        });
    test_int(ctx, 10);

    ecs.progress();

    test_int(ctx, 11);
}

